const ROYAL_URL = 'https://royal4x4.com.br/Veiculos';
function rlEnv(name) { try { return String($env[name] || $vars?.[name] || '').trim(); } catch (_) { try { return String($env[name] || '').trim(); } catch (_) { return ''; } } }
