 const priceIndex=lines.findLastIndex(x=>rlPrice(x)!==null);
 if(priceIndex<0) return null;
 const price=rlPrice(lines[priceIndex]);if(!Number.isFinite(price)||price<=0) return null;
 const pre=lines.slice(Math.max(0,priceIndex-18),priceIndex);
 const yearIndex=pre.findLastIndex(x=>/\b(?:19|20)\d{2}\s*\/\s*(?:19|20)\d{2}\b/.test(x));
 if(yearIndex<0) return null;
 const yearMatch=pre[yearIndex].match(/\b((?:19|20)\d{2}\s*\/\s*(?:19|20)\d{2})\b/);
 const year=yearMatch?.[1]?.replace(/\s/g,'');
