 const titleCandidates=pre.slice(Math.max(0,yearIndex-8),yearIndex).filter(x=>x.length>=2&&x.length<=135&&!/^(Ver mais|BLINDADO|De R\$|R\$|Veiculos|Pesquisar|Filtros|Compartilhar)$/i.test(x));
 if(titleCandidates.length<2) return null;
 const name=titleCandidates.at(-2),version=titleCandidates.at(-1);
 if(/^(\d+ km|R\$)/i.test(name)||/(veiculos encontrados|buscar|filtros)/i.test(name))return null;
 const blindado=pre.slice(Math.max(0,yearIndex-10),yearIndex).some(x=>rlNorm(x)==='blindado');
 return {name,version,year,km,price,blindado};
}
