 const raw=String(html||'');
 if(raw.length<10000) throw Error('SITE_BODY_TOO_SHORT');
 const countMatch=rlPlain(rlText(raw).slice(0,350).join(' ')).match(/([\d.]+)\s+ve[ií]culos?\s+encontrados/i)
   || raw.replace(/<[^>]+>/g,' ').match(/([\d.]+)\s+ve[ií]culos?\s+encontrados/i);
