 if(!/^gemini-[\w.-]+$/.test(model))throw Error('ROYAL_MODEL_INVALID');
 const instructions=`Você é um classificador de intenções de clientes da loja Royal 4x4. Devolva somente JSON com action ("search","next","hello","human","details"), query (marca/modelo que consta no pedido, ou vazio), max_price, min_price, min_year, max_km (números ou null), blindado (boolean ou null), page (inteiro ou null), index (inteiro ou null). Nunca invente carros, preços, links, opções ou características. A frase "mais opções" ou "próximos" significa next. Se cliente pedir vendedor, negociação, financiamento, avaliação ou visita, use human. "quero ver o 2" = details,index=2. Para busca genérica use query vazio.`;
 const body={system_instruction:{parts:[{text:instructions}]},contents:[{role:'user',parts:[{text:JSON.stringify({message:text,previous_search:state.filter||{},page:state.page||1})}]}],
 generationConfig:{temperature:0.1,maxOutputTokens:220,responseMimeType:'application/json'}};
 const response=await this.helpers.httpRequest({method:'POST',url:'https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+':generateContent',
 headers:{'Content-Type':'application/json','x-goog-api-key':geminiKey},json:true,body,timeout:30000});
 const candidate=response?.candidates?.[0];if(!candidate||candidate.finishReason!=='STOP')throw Error('ROYAL_GEMINI_NOT_FINISHED');
 const content=candidate.content?.parts?.map(p=>p.text||'').join('')||'';
 const parsed=JSON.parse(content.replace(/^```json\s*|\s*```$/g,''));
 if(!['search','next','hello','human','details'].includes(parsed.action))throw Error('ROYAL_GEMINI_ACTION_INVALID');
 return parsed;
}
function makeReply(stock,ai,state,text){
 if(ai.action==='hello')return {reply:`Olá! Sou a assistente virtual da Royal 4x4. Posso consultar nosso estoque atualizado de ${stock.declared} veículos. Você procura alguma marca, modelo ou faixa de preço?`,stage:'Qualificacao',handoff:false,state:{...state,stock_fetched_at:stock.fetched_at,stock_count:stock.declared}};
 if(ai.action==='human')return {reply:'Vou encaminhar sua mensagem à equipe da Royal 4x4 para ajudar com negociação ou outras informações. Um atendente continuará por aqui.',stage:'Atendimento humano',handoff:true,state:{...state,stock_fetched_at:stock.fetched_at,stock_count:stock.declared}};
 let filter=ai.action==='next'||ai.action==='details'?state.filter||{}:{query:String(ai.query||'').slice(0,85),max_price:ai.max_price||null,min_price:ai.min_price||null,min_year:ai.min_year||null,max_km:ai.max_km??null,blindado:ai.blindado===true?true:null};
 if(ai.action==='details'){
   const old=state.last_results||[];const idx=Number(ai.index);const prev=Number.isInteger(idx)&&idx>0&&idx<=old.length?old[idx-1]:null;
   const car=prev?stock.items.find(x=>x.id===prev):null;
   if(!car)return {reply:'Não consegui localizar essa opção no estoque atual. Me diga o modelo ou faça uma nova busca, por favor.',stage:'Qualificacao',handoff:false,state:{...state,last_results:[],stock_fetched_at:stock.fetched_at,stock_count:stock.declared}};
   return {reply:rlFormatVehicle(car,1)+'\n\nPosso apresentar outras opções ou chamar um vendedor.',stage:'Qualificacao',handoff:false,state:{...state,last_results:[car.id],stock_fetched_at:stock.fetched_at,stock_count:stock.declared}};
 }
 let matches=stock.items.filter(x=>rlMatches(x,filter));
 let page=ai.action==='next'?Number(state.page||1)+1:Math.max(1,Math.min(200,Number(ai.page)||1));
 const pages=Math.max(1,Math.ceil(matches.length/5));if(page>pages)page=pages;
 const list=matches.slice((page-1)*5,page*5);
 const label=filter.query?' para '+filter.query:'';
