   `${matches.length} veículo(s) encontrado(s)${label}. Página ${page}/${pages}:\n\n${list.map((x,i)=>rlFormatVehicle(x,i+1)).join('\n\n')}\n\n${page<pages?'Responda "mais opções" para ver os próximos. ':'Diga outro modelo para fazer nova busca. '}Para falar com um vendedor, é só pedir.`;
 return {reply:body.slice(0,8500),stage:matches.length?'Qualificacao':'Qualificacao',handoff:false,state:{...state,filter,page,last_results:list.map(x=>x.id),stock_fetched_at:stock.fetched_at,stock_count:stock.declared}};
}
const results=[];
const pending=await this.helpers.httpRequest({method:'GET',url:base+'/rest/v1/royal_stock_turns?select=chat_id,phase,quiet_until,pending&tenant_id=eq.'+tenantId+'&order=updated_at.asc&limit=30',headers,json:true,timeout:12000});
if(!Array.isArray(pending))throw Error('ROYAL_QUEUE_READ_INVALID');
if(pending.some(r=>Array.isArray(r.pending)&&r.pending.length)&&(!evoBase||!evoKey||!geminiKey))return [{json:{ok:false,reason:'ROYAL_RUNTIME_CREDENTIALS_MISSING',action:'Configure Evolution e Gemini antes de liberar o atendimento.'}}];
