   const state=c.state&&typeof c.state==='object'?c.state:{};
   let out;
   try{
     if(text.includes('[Áudio não suportado')||text.includes('[Mensagem não textual')){
       out={reply:'Por enquanto, consigo consultar o estoque por texto. Pode escrever qual carro procura?',stage:'Qualificacao',handoff:false,state};
     }else{
       // Live inventory at each conversational turn, not a saved vehicle catalog.
       const stockHtml=await this.helpers.httpRequest({method:'GET',url:ROYAL_URL,headers:{'User-Agent':'Mozilla/5.0 (compatible; NORIA-Royal-Stock/1.0)','Accept':'text/html'},json:false,timeout:35000});
       const html=typeof stockHtml==='string'?stockHtml:String(stockHtml?.body||stockHtml?.data||'');
       const stock=rlParseInventory(html);
       const ai=await classify.call(this,text,state,c.settings||{});
       out=makeReply(stock,ai,state,text);
     }
   }catch(error){
     // Fail closed, not invented inventory data or fees.
     out={reply:'Não consegui consultar o estoque atualizado com segurança agora. Vou encaminhar para a equipe verificar e continuar por aqui.',stage:'Atendimento humano',handoff:true,state:{...state,last_error:String(error?.message||error).slice(0,180)}};
   }
   const preparedData={token:c.token,revision:c.revision,reply:out.reply,stage:out.stage,handoff:out.handoff,state:out.state};
   const prep=await rpc.call(this,'prepare',chat,preparedData);
   if(!prep?.ok){results.push({chat,result:'aborted_before_send'});continue;}
   prepared=true;
   sendAttempted=true;
   const number=chat.replace(/@.+$/,'');
   const sent=await this.helpers.httpRequest({method:'POST',url:evoBase+'/message/sendText/'+encodeURIComponent('Royal 4x4'),
     headers:{apikey:evoKey,'Content-Type':'application/json'},body:{number,text:out.reply},json:true,timeout:30000});
   const outboundId=String(sent?.key?.id||sent?.message?.key?.id||sent?.id||'');
   if(!outboundId)throw Error('ROYAL_DELIVERY_MESSAGE_ID_MISSING');
   const committed=await rpc.call(this,'finish',chat,{token:c.token,message_id:outboundId});
   if(!committed?.ok)throw Error('ROYAL_DELIVERY_NOT_COMMITTED');
   results.push({chat,result:'sent',count:out.state.stock_count||null});
 }catch(error){
   if(prepared){try{await rpc.call(this,'uncertain',chat,{token:c.token});}catch(_){}}
   results.push({chat,result:prepared?'delivery_uncertain':'failed_before_send',error:String(error?.message||error).slice(0,200)});
 }
}
return results.length?results.map(r=>({json:r})):[{json:{ok:true,processed:0}}];

